            }
            if (updateProjectRequest.PromptLimitOption.IsSet)
                if (updateProjectRequest.PromptLimitOption.Value != null)
                    writer.WriteNumber("prompt_limit", updateProjectRequest.PromptLimitOption.Value!.Value);
                else
